struct Base {
    int base_member;
};
struct Derived : Base {
    int derived_member;
};

void example() {
    struct Derived d;
    struct Base *bp = (struct Base *)&d; // Upcasting derived pointer to base pointer
    // Accessing base member through base pointer
    printf("Base member: %d\n", bp->base_member);
}
